#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

#define HSIZE (1 << 19)
#define HMASK (HSIZE - 1)

typedef struct {
    uint64_t *keys;
} HashSet;

static void hs_init(HashSet *h) {
    h->keys = (uint64_t*)calloc(HSIZE, sizeof(uint64_t));
    if (!h->keys) exit(1);
}

static inline uint64_t mix(uint64_t x) {
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

static int hs_contains(const HashSet *h, uint64_t key) {
    uint64_t idx = mix(key) & HMASK;
    while (h->keys[idx] != 0) {
        if (h->keys[idx] == key) return 1;
        idx = (idx + 1) & HMASK;
    }
    return 0;
}

static void hs_insert(HashSet *h, uint64_t key) {
    uint64_t idx = mix(key) & HMASK;
    while (h->keys[idx] != 0) {
        if (h->keys[idx] == key) return;
        idx = (idx + 1) & HMASK;
    }
    h->keys[idx] = key;
}

static inline uint64_t encode(const char *s, int len) {
    uint64_t code = 0;
    for (int i = 0; i < len; ++i) {
        code = code * 26 + (uint64_t)(s[i] - 'a');
    }
    return ((uint64_t)len << 56) | code;
}

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    HashSet full, suffix, prefix;
    hs_init(&full);
    hs_init(&suffix);
    hs_init(&prefix);

    char s[11];

    for (int k = 1; k <= N; ++k) {
        scanf("%s", s);

        if (k > 1) {
            if (hs_contains(&full, encode(s, 10))) {
                printf("%s\n", s);
                return 0;
            }

            for (int x = 1; x <= 9; ++x) {
                uint64_t key1 = encode(s, x);
                uint64_t key2 = encode(s + x, 10 - x);
                if (hs_contains(&suffix, key1) && hs_contains(&prefix, key2)) {
                    printf("%s\n", s);
                    return 0;
                }
            }
        }

        hs_insert(&full, encode(s, 10));

        for (int x = 1; x <= 9; ++x) {
            hs_insert(&suffix, encode(s + 10 - x, x));
            hs_insert(&prefix, encode(s, x));
        }
    }

    printf("ok\n");
    return 0;
}
